// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport android.content.ClipDataimport android.content.ClipboardManagerimport android.content.Contextimport android.content.Intentimport android.content.pm.ApplicationInfoimport android.content.pm.PackageManagerimport android.net.Uri/** * NOUS — App + Clipboard Services (Module 10 v2 — Step 10.7). * * Service interfaces wrapping Android `PackageManager`, `ClipboardManager`, * and URL-launching intents for handler testability. * * ## Why interfaces? * * Same as [ConnectivityServices.kt] / [ExtendedConnectivityServices.kt] — * thin wrappers so handlers can be unit-tested with fakes instead of * requiring Robolectric + real Android system services. */// ──────────────────────────────────────────────────────────────────────────// App launcher service (wraps PackageManager + startActivity)// ──────────────────────────────────────────────────────────────────────────/** * Wraps the subset of [PackageManager] + `startActivity` that [AppHandler] uses. */interface AppLauncherService {    /** Launch an app by its package name. Returns true if launch succeeded. */    fun launchByPackage(packageName: String): Boolean    /**     * Find a package whose display name fuzzy-matches [appName].     *     * Example: "YouTube" → `com.google.android.youtube`.     *     * @return the package name, or null if no match found.     */    fun findPackageByName(appName: String): String?    /** Get the friendly display name of [packageName], or null if not installed. */    fun getAppDisplayName(packageName: String): String?    /** True if [packageName] is currently the foreground app. */    fun isAppInForeground(packageName: String): Boolean}/** * Android [AppLauncherService] backed by [PackageManager] + [AppNameMatcher]. */class AndroidAppLauncherService(    private val context: Context,    private val packageManager: PackageManager,    private val appNameMatcher: AppNameMatcher = AppNameMatcher(),) : AppLauncherService {    override fun launchByPackage(packageName: String): Boolean = try {        val intent = packageManager.getLaunchIntentForPackage(packageName)        if (intent != null) {            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)            context.startActivity(intent)            true        } else {            Timber.tag("AndroidAppLauncherService").w("No launch intent for $packageName")            false        }    } catch (t: Throwable) {        Timber.tag("AndroidAppLauncherService").w("launchByPackage failed for $packageName", t)        false    }    override fun findPackageByName(appName: String): String? {        val installedApps = getInstalledAppNames()        return appNameMatcher.findBestMatch(appName, installedApps)?.first    }    override fun getAppDisplayName(packageName: String): String? = try {        val info = packageManager.getApplicationInfo(packageName, 0)        packageManager.getApplicationLabel(info).toString()    } catch (t: Throwable) {        null    }    override fun isAppInForeground(packageName: String): Boolean {        // Real impl uses ActivityManager.getRunningAppProcesses() — but that's        // restricted since Android 5.0 (only returns the caller's own process).        // For accuracy, we'd use UsageStatsManager (requires PACKAGE_USAGE_STATS        // special permission). For now, return false — idempotent skip is a        // nice-to-have optimization, not a correctness requirement.        return false    }    /** Get all installed (non-system) apps as (packageName, displayName) pairs. */    private fun getInstalledAppNames(): List<Pair<String, String>> = try {        val apps = packageManager.getInstalledApplications(0)        apps            .filter { (it.flags and ApplicationInfo.FLAG_SYSTEM) == 0 }  // exclude system apps            .map { it.packageName to packageManager.getApplicationLabel(it).toString() }    } catch (t: Throwable) {        Timber.tag("AndroidAppLauncherService").w("getInstalledAppNames failed", t)        emptyList()    }}// ──────────────────────────────────────────────────────────────────────────// URL launcher service (wraps startActivity for ACTION_VIEW)// ──────────────────────────────────────────────────────────────────────────/** * Wraps URL-launching via `Intent.ACTION_VIEW`. * * Separated from [AppLauncherService] because URL validation (reject * `file://`, `content://`) is a security concern — keep it isolated. */interface UrlLauncherService {    /**     * Open [url] in the default app (browser for http/https).     *     * @return true if an app was available to handle the URL.     */    fun openUrl(url: String): Boolean    /**     * Validate that [url] uses an allowed scheme.     *     * Allowed: http, https, mailto, tel, sms, geo, market, intent (custom     * schemes are user-defined apps).     * Disallowed: file, content (security — could leak local files).     */    fun isSchemeAllowed(url: String): Boolean}/** * Android [UrlLauncherService] backed by `Intent.ACTION_VIEW`. */class AndroidUrlLauncherService(    private val context: Context,) : UrlLauncherService {    override fun openUrl(url: String): Boolean = try {        val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url))            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)        context.startActivity(intent)        true    } catch (t: Throwable) {        Timber.tag("AndroidUrlLauncherService").w("openUrl failed for $url", t)        false    }    override fun isSchemeAllowed(url: String): Boolean {        val scheme = try {            Uri.parse(url).scheme?.lowercase()        } catch (t: Throwable) {            return false        }        if (scheme == null) return false  // no scheme = relative URL = reject        return scheme in ALLOWED_SCHEMES    }    companion object {        /** URL schemes NOUS is allowed to open. */        val ALLOWED_SCHEMES = setOf(            "http", "https",      // web            "mailto", "tel", "sms", // communications            "geo",                 // maps            "market",              // Play Store            "intent",              // Android intent URIs (with safeguards)        )        /** URL schemes explicitly blocked for security. */        val BLOCKED_SCHEMES = setOf(            "file",     // could leak local files            "content",  // could leak content provider data        )    }}// ──────────────────────────────────────────────────────────────────────────// Clipboard service (wraps ClipboardManager)// ──────────────────────────────────────────────────────────────────────────/** * Wraps [ClipboardManager] for [ClipboardHandler]. */interface ClipboardService {    /** Copy [text] to the system clipboard. Returns true on success. */    fun copyText(text: String): Boolean    /** Get the current clipboard text, or null if empty/non-text. */    fun getCurrentText(): String?}/** * Android [ClipboardService] backed by [ClipboardManager]. */class AndroidClipboardService(    private val clipboardManager: ClipboardManager,) : ClipboardService {    override fun copyText(text: String): Boolean = try {        val clip = ClipData.newPlainText("NOUS", text)        clipboardManager.setPrimaryClip(clip)        true    } catch (t: Throwable) {        Timber.tag("AndroidClipboardService").w("copyText failed", t)        false    }    override fun getCurrentText(): String? {        return try {            val clip = clipboardManager.primaryClip ?: return null            if (clip.itemCount == 0) return null            clip.getItemAt(0).text?.toString()        } catch (t: Throwable) {            null        }    }}// ──────────────────────────────────────────────────────────────────────────// App name matcher (fuzzy)// ──────────────────────────────────────────────────────────────────────────/** * Fuzzy app-name matcher for [AppLauncherService.findPackageByName]. * * ## Algorithm * *  1. Exact match (case-insensitive): "YouTube" == "youtube" → instant match. *  2. Contains: "YouTube" contains "tube" → match (lower priority). *  3. Levenshtein distance: "Youtoob" → "YouTube" (distance 2) → match if *     distance <= threshold (default 3). * * Returns the best match (highest score), or null if no match meets the * threshold. * * ## Testability * * Pure functions — fully testable without Android. */class AppNameMatcher(    /** Max Levenshtein distance to consider a fuzzy match (default 3). */    private val maxLevenshteinDistance: Int = 3,) {    /**     * Find the best match for [query] in [installedApps].     *     * @param query user's spoken/typed app name (e.g., "YouTube", "youtoob").     * @param installedApps list of (packageName, displayName) pairs.     * @return best (packageName, displayName) match, or null.     */    fun findBestMatch(        query: String,        installedApps: List<Pair<String, String>>,    ): Pair<String, String>? {        if (query.isBlank() || installedApps.isEmpty()) return null        val queryLower = query.lowercase().trim()        // 1. Exact match (case-insensitive).        val exact = installedApps.firstOrNull { (_, name) ->            name.lowercase().trim() == queryLower        }        if (exact != null) return exact        // 2. Query contains display name or vice versa.        val contains = installedApps.firstOrNull { (_, name) ->            val nameLower = name.lowercase().trim()            nameLower.contains(queryLower) || queryLower.contains(nameLower)        }        if (contains != null) return contains        // 3. Levenshtein distance.        var bestMatch: Pair<String, String>? = null        var bestDistance = Int.MAX_VALUE        for ((pkg, name) in installedApps) {            val dist = levenshtein(queryLower, name.lowercase().trim())            if (dist < bestDistance && dist <= maxLevenshteinDistance) {                bestDistance = dist                bestMatch = pkg to name            }        }        return bestMatch    }    /**     * Compute Levenshtein distance between [a] and [b].     *     * Pure function — O(a.length × b.length) dynamic programming.     */    internal fun levenshtein(a: String, b: String): Int {        val m = a.length        val n = b.length        if (m == 0) return n        if (n == 0) return m        val dp = Array(m + 1) { IntArray(n + 1) }        for (i in 0..m) dp[i][0] = i        for (j in 0..n) dp[0][j] = j        for (i in 1..m) {            for (j in 1..n) {                val cost = if (a[i - 1] == b[j - 1]) 0 else 1                dp[i][j] = minOf(                    dp[i - 1][j] + 1,        // deletion                    dp[i][j - 1] + 1,        // insertion                    dp[i - 1][j - 1] + cost,  // substitution                )            }        }        return dp[m][n]    }}